<!-- @FIGURE_UI_BEGIN -->
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px;display:block">The default view matches the compact textbook figure: the airplane, horizontal reference line, two dashed sight lines, road points A and B, and the given angles only. The steeper sight line to A is labeled 49°, and the shallower sight line to B is labeled 25°.</span><span><button onclick="prevStep()">◀</button> <span id="stepLabel">1/3 — Faithful source diagram</span> <button onclick="nextStep()">▶</button></span><button id="diagramViewInput" onclick="trigger_diagramView()">Diagram view: source figure</button><label>Angle to A: <output id="angleToAVal">49</output><input id="angleToAInput" type="range" min="40" max="65" step="1" value="49" oninput="document.getElementById('angleToAVal').value=this.value;update_angleToA(+this.value)"></label><label>Angle to B: <output id="angleToBVal">25</output><input id="angleToBInput" type="range" min="10" max="35" step="1" value="25" oninput="document.getElementById('angleToBVal').value=this.value;update_angleToB(+this.value)"></label>
