// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 450;
draw.viewbox(0, 0, W, H);

var root = draw.group();

var state = {
  diagramView: 'sourceFigure',
  angleToA: 49,
  angleToB: 25,
  step: 0
};

var demoSteps = [
  {
    title: 'Faithful source diagram',
    narration: 'The default view matches the compact textbook figure: the airplane, horizontal reference line, two dashed sight lines, road points A and B, and the given angles only. The steeper sight line to A is labeled 49°, and the shallower sight line to B is labeled 25°.',
    state: { diagramView: 'sourceFigure', angleToA: 49, angleToB: 25 }
  },
  {
    title: 'Reveal the right-triangle setup',
    narration: 'The construction view lightly adds the vertical altitude and horizontal road distances, showing that both sight lines can be treated as right triangles sharing the same height.',
    state: { diagramView: 'construction', angleToA: 49, angleToB: 25 }
  },
  {
    title: 'Explore angle size',
    narration: 'Changing the angles redraws the sight lines while keeping the road horizontal. Larger depression angles remain steeper and meet the road closer to the airplane; smaller angles remain shallower and meet farther away.',
    state: { diagramView: 'exploreAngles', angleToA: 49, angleToB: 25 }
  }
];

var viewOrder = ['sourceFigure', 'construction', 'exploreAngles'];
var viewLabel = {
  sourceFigure: 'source figure',
  construction: 'construction',
  exploreAngles: 'explore angles'
};

var S = { x: 138, y: 110 };
var defaultAltitude = 190;
var roadRight = 580;
var targetRightLimit = 560;

function rad(deg) {
  return deg * Math.PI / 180;
}

function pointAt(cx, cy, r, a) {
  return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
}

function arcPath(cx, cy, r, a1, a2) {
  var p1 = pointAt(cx, cy, r, a1);
  var p2 = pointAt(cx, cy, r, a2);
  var large = Math.abs(a2 - a1) > Math.PI ? 1 : 0;
  return 'M ' + p1.x + ' ' + p1.y + ' A ' + r + ' ' + r + ' 0 ' + large + ' 1 ' + p2.x + ' ' + p2.y;
}

function addText(g, str, x, y, size, opts) {
  opts = opts || {};
  var t = g.text(str).font({
    family: opts.family || 'serif',
    size: size || 18,
    anchor: opts.anchor || 'middle'
  }).fill(opts.fill || '#111');
  t.center(x, y);
  if (opts.halo !== false) {
    t.attr({
      'paint-order': 'stroke',
      stroke: opts.haloColor || '#fff',
      'stroke-width': opts.haloWidth || 4,
      'stroke-linejoin': 'round'
    });
  }
  return t;
}

function addSoftBoxText(g, str, x, y, w, h, color) {
  var grp = g.group();
  grp.rect(w, h).radius(5).fill({ color: '#fff', opacity: 0.9 }).stroke({ color: color, width: 1, opacity: 0.5 });
  grp.move(x - w / 2, y - h / 2);
  grp.text(str).font({ family: 'serif', size: 15, anchor: 'middle' }).center(x, y).fill(color);
  return grp;
}

function drawDoubleArrow(g, x1, y1, x2, y2, color) {
  var grp = g.group();
  grp.line(x1, y1, x2, y2).stroke({ color: color, width: 1.25, opacity: 0.78 });
  var ah = 5;
  grp.path('M ' + x1 + ' ' + y1 + ' l ' + ah + ' -3.5 M ' + x1 + ' ' + y1 + ' l ' + ah + ' 3.5')
    .fill('none').stroke({ color: color, width: 1.25, linecap: 'round', opacity: 0.78 });
  grp.path('M ' + x2 + ' ' + y2 + ' l -' + ah + ' -3.5 M ' + x2 + ' ' + y2 + ' l -' + ah + ' 3.5')
    .fill('none').stroke({ color: color, width: 1.25, linecap: 'round', opacity: 0.78 });
  return grp;
}

function drawAirplane(g, x, y) {
  var plane = g.group();
  plane.translate(x, y);
  plane.scale(0.5);

  plane.path('M -108 -8 C -73 -20 -24 -18 18 -6 C 35 -1 34 11 14 15 C -24 23 -75 17 -110 7 C -124 3 -124 -4 -108 -8 Z')
    .fill('#aab7d0').stroke({ color: '#3d548b', width: 3, linejoin: 'round' });
  plane.path('M -30 -14 L -76 -50 L -42 -45 L 22 -10 Z')
    .fill('#5f76a8').stroke({ color: '#30477b', width: 3, linejoin: 'round' });
  plane.path('M -34 10 L -82 39 L -48 38 L 17 12 Z')
    .fill('#5f76a8').stroke({ color: '#30477b', width: 3, linejoin: 'round' });
  plane.path('M 8 -7 L 50 -34 L 68 -31 L 31 0 Z')
    .fill('#5f76a8').stroke({ color: '#30477b', width: 3, linejoin: 'round' });
  plane.path('M -103 -3 L -154 8 L -157 15 L -96 9 Z')
    .fill('#5f76a8').stroke({ color: '#30477b', width: 3, linejoin: 'round' });
  plane.circle(10).center(-78, 19).fill('#223b70');
  plane.circle(10).center(-43, 22).fill('#223b70');
  plane.path('M -92 -5 C -54 -1 -16 -1 17 6').fill('none').stroke({ color: '#52699d', width: 2 });

  plane.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Airplane: both angles are measured from the same horizontal line through the airplane.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Angles of depression', 'The airplane supplies the horizontal reference line. Each angle is measured downward from that reference to a line of sight.');
    });

  return plane;
}

function geometry() {
  var aA = Math.max(state.angleToA, state.angleToB + 1);
  var aB = state.angleToB;
  var hFit = (targetRightLimit - S.x) * Math.tan(rad(aB));
  var altitude = Math.min(defaultAltitude, Math.max(70, hFit));
  if (state.angleToB === 25 && state.angleToA === 49) altitude = defaultAltitude;

  var roadY = S.y + altitude;
  var dxA = altitude / Math.tan(rad(aA));
  var dxB = altitude / Math.tan(rad(aB));
  return {
    aA: aA,
    aB: aB,
    roadY: roadY,
    AX: S.x + dxA,
    BX: S.x + dxB,
    PX: S.x,
    altitude: altitude
  };
}

function render() {
  root.clear();
  root.rect(W, H).fill('#fff');

  var geo = geometry();
  var roadStart = Math.max(145, Math.min(geo.AX - 115, geo.PX + 18));
  var roadEnd = roadRight;

  if (state.diagramView === 'construction') {
    var triB = root.polygon([[geo.PX, S.y], [geo.PX, geo.roadY], [geo.BX, geo.roadY]])
      .fill({ color: '#fff1c6', opacity: 0.2 }).stroke('none');
    var triA = root.polygon([[geo.PX, S.y], [geo.PX, geo.roadY], [geo.AX, geo.roadY]])
      .fill({ color: '#d9ecff', opacity: 0.28 }).stroke('none');

    triA.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Nearer triangle: a larger angle reaches the road after a shorter horizontal run.', e); })
      .on('mouseleave', function () { hideTooltip(); });
    triB.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Farther triangle: a smaller angle travels farther before reaching the road.', e); })
      .on('mouseleave', function () { hideTooltip(); });
  }

  var ref = root.line(S.x, S.y, roadRight, S.y)
    .stroke({ color: '#008b8b', width: 1.7, dasharray: '7 6', linecap: 'butt' });
  ref.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Horizontal reference line: both depression angles start here.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Horizontal reference', 'The teal dashed line is parallel to the road. Angles of depression are measured downward from this horizontal, not upward from the road.');
    });

  var road = root.line(roadStart, geo.roadY, roadEnd, geo.roadY)
    .stroke({ color: '#111', width: 2.3, linecap: 'butt' });
  road.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Horizontal road: A is nearer and B is farther along the same line.', e); })
    .on('mouseleave', function () { hideTooltip(); });

  var sightB = root.line(S.x, S.y, geo.BX, geo.roadY)
    .stroke({ color: '#777', width: 2, dasharray: '7 6', linecap: 'round' });
  var sightA = root.line(S.x, S.y, geo.AX, geo.roadY)
    .stroke({ color: '#777', width: 2, dasharray: '7 6', linecap: 'round' });

  sightA.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Sight line to A: steeper, nearer, and labeled ' + geo.aA + '°.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('The 49° sight line', 'The larger angle of depression is the steeper line. Because it drops more quickly, it reaches the road at the nearer point A.');
    });

  sightB.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Sight line to B: shallower, farther, and labeled ' + geo.aB + '°.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('The 25° sight line', 'The smaller angle of depression is the shallower line. It travels farther horizontally before meeting the road, so it reaches point B.');
    });

  var bArcR = 45;
  var aArcR = 72;
  var pathB = root.path(arcPath(S.x, S.y, bArcR, 0, rad(geo.aB)))
    .fill('none').stroke({ color: '#555', width: 1.35 });
  var pathA = root.path(arcPath(S.x, S.y, aArcR, 0, rad(geo.aA)))
    .fill('none').stroke({ color: '#555', width: 1.35 });

  pathB.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(geo.aB + '° is measured from the horizontal to the shallow B line.', e); })
    .on('mouseleave', function () { hideTooltip(); });
  pathA.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(geo.aA + '° is measured from the horizontal to the steep A line.', e); })
    .on('mouseleave', function () { hideTooltip(); });

  if (state.diagramView === 'construction') {
    root.line(geo.PX, S.y, geo.PX, geo.roadY).stroke({ color: '#333', width: 1.5, opacity: 0.62 });
    root.circle(3.2).center(geo.PX, geo.roadY).fill({ color: '#333', opacity: 0.5 });
    root.path('M ' + geo.PX + ' ' + (geo.roadY - 14) + ' L ' + (geo.PX + 14) + ' ' + (geo.roadY - 14) + ' L ' + (geo.PX + 14) + ' ' + geo.roadY)
      .fill('none').stroke({ color: '#222', width: 1.3, opacity: 0.65 });

    addText(root, 'P', geo.PX - 12, geo.roadY + 20, 15, { haloWidth: 4, fill: '#333' });

    var y1 = geo.roadY + 34;
    var y2 = geo.roadY + 57;
    drawDoubleArrow(root, geo.PX, y1, geo.AX, y1, '#2f5597');
    addText(root, 'x', (geo.PX + geo.AX) / 2, y1 - 12, 15, { fill: '#2f5597', haloWidth: 4 });
    drawDoubleArrow(root, geo.AX, y2, geo.BX, y2, '#8a4b08');
    addText(root, 'd', (geo.AX + geo.BX) / 2, y2 - 12, 15, { fill: '#8a4b08', haloWidth: 4 });

    addSoftBoxText(root, 'tan(' + geo.aA + '°)=h/x', 423, 151, 126, 30, '#2f5597')
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('For A, the adjacent side is the shorter distance x.', e); })
      .on('mouseleave', function () { hideTooltip(); });
    addSoftBoxText(root, 'tan(' + geo.aB + '°)=h/(x+d)', 450, 190, 154, 30, '#8a4b08')
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('For B, the adjacent side is longer: x + d.', e); })
      .on('mouseleave', function () { hideTooltip(); });
  }

  addText(root, 'A', geo.AX, geo.roadY + 19, 20, { haloWidth: 4 });
  addText(root, 'B', geo.BX, geo.roadY + 19, 20, { haloWidth: 4 });

  var labelBPos = pointAt(S.x, S.y, 61, rad(geo.aB / 2));
  var labelAPos = pointAt(S.x, S.y, 89, rad((geo.aA + geo.aB) / 2 + 4));
  addText(root, geo.aB + '°', labelBPos.x + 7, labelBPos.y - 3, 16, { haloWidth: 5 });
  addText(root, geo.aA + '°', labelAPos.x + 13, labelAPos.y + 1, 16, { haloWidth: 5 });

  drawAirplane(root, 95, 96);

  if (state.diagramView === 'exploreAngles') {
    sightA.stroke({ color: '#555', width: 2.2, dasharray: '7 6' });
    sightB.stroke({ color: '#888', width: 2, dasharray: '7 6' });
  }

  var btn = document.getElementById('diagramViewInput');
  if (btn) btn.textContent = 'Diagram view: ' + viewLabel[state.diagramView];

  var narr = document.getElementById('demoNarration');
  if (narr) narr.textContent = demoSteps[state.step].narration;

  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (state.step + 1) + '/' + demoSteps.length + ' — ' + demoSteps[state.step].title;
}

function setUiValues() {
  var a = document.getElementById('angleToAInput');
  var b = document.getElementById('angleToBInput');
  var av = document.getElementById('angleToAVal');
  var bv = document.getElementById('angleToBVal');
  if (a) a.value = state.angleToA;
  if (b) b.value = state.angleToB;
  if (av) av.value = state.angleToA;
  if (bv) bv.value = state.angleToB;
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[state.step].state;
  state.diagramView = st.diagramView;
  update_angleToA(st.angleToA, true);
  update_angleToB(st.angleToB, true);
  setUiValues();
  render();
}

function update_angleToA(v, skipRender) {
  state.angleToA = Math.max(40, Math.min(65, Math.round(v)));
  if (state.angleToA <= state.angleToB) state.angleToA = state.angleToB + 1;
  if (!skipRender) render();
}

function update_angleToB(v, skipRender) {
  state.angleToB = Math.max(10, Math.min(35, Math.round(v)));
  if (state.angleToB >= state.angleToA) state.angleToB = state.angleToA - 1;
  if (!skipRender) render();
}

function trigger_diagramView() {
  var idx = viewOrder.indexOf(state.diagramView);
  state.diagramView = viewOrder[(idx + 1) % viewOrder.length];
  state.step = state.diagramView === 'sourceFigure' ? 0 : (state.diagramView === 'construction' ? 1 : 2);
  render();
}

function nextStep() {
  applyStep((state.step + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((state.step - 1 + demoSteps.length) % demoSteps.length);
}

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

